-- TEST audited learning reader only: no source writes, secrets or capture activation.
begin;
set local search_path=public,extensions,pg_catalog;set local lock_timeout='3s';set local statement_timeout='30s';
lock table of_test_deploy.migrations in share row exclusive mode;
